/*Table structure for table `product_knowledge` */

DROP TABLE IF EXISTS `product_knowledge`;

CREATE TABLE `product_knowledge` (
  `id` int(20) NOT NULL AUTO_INCREMENT,
  `product_name` varchar(100) DEFAULT NULL,
  `product_detail` longblob DEFAULT NULL,
  `product_image` varchar(100) DEFAULT NULL,
  `dezcription` longblob DEFAULT NULL,
  `created_date` datetime DEFAULT NULL,
  `product_main_image` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

/*Data for the table `product_knowledge` */

insert  into `product_knowledge`(`id`,`product_name`,`product_detail`,`product_image`,`dezcription`,`created_date`,`product_main_image`) values 
(6,'U Store','<div class=\"ql-editor ql-blank\" data-gramm=\"false\" contenteditable=\"true\"><p class=\"ql-align-center\"><span style=\"color: black;\">uStore adalah fitur terbaru dari aplikasi by.U yang memungkinkan pelanggan existing untuk melakukan pembelian produk telco dan merchandise hanya di dalam aplikasi. Dengan uStore, pelanggan dapat dengan mudah dan cepat membeli berbagai produk telco, seperti paket data, pulsa, dan voucher, serta produk – produk merchandise &amp; produk kolaborasi by.U.</span></p><p><img src=\"data:image/jpeg;base64,\"></p></div><div class=\"ql-clipboard\" contenteditable=\"true\" tabindex=\"-1\"></div><div class=\"ql-tooltip ql-hidden\"><a class=\"ql-preview\" target=\"_blank\" href=\"about:blank\"></a><input type=\"text\" data-formula=\"e=mc^2\" data-link=\"https://quilljs.com\" data-video=\"Embed URL\"><a class=\"ql-action\"></a><a class=\"ql-remove\"></a></div>','1737593002_8b5bca45afa39f34720d.png',NULL,NULL,'1737593002_39f89afc3b8f62d5f583.jpg');

