/*Table structure for table `questions.bak` */

DROP TABLE IF EXISTS `questions.bak`;

CREATE TABLE `questions.bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question` text NOT NULL,
  `option_a` varchar(255) NOT NULL,
  `option_b` varchar(255) NOT NULL,
  `option_c` varchar(255) NOT NULL,
  `option_d` varchar(255) NOT NULL,
  `correct_option` char(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

/*Data for the table `questions.bak` */

insert  into `questions.bak`(`id`,`question`,`option_a`,`option_b`,`option_c`,`option_d`,`correct_option`) values 
(1,'Apa kepanjangan dari GSM dalam dunia telekomunikasi?','Global System for Mobile Communications','General Satellite Module','Global Signal Management','General System for Mobile Operations','A'),
(2,'Apa fungsi utama dari BTS dalam jaringan seluler?','Menghubungkan pengguna langsung ke internet','Mengirim dan menerima sinyal dari perangkat seluler','Mengatur alamat IP pengguna','Menyimpan data pelanggan','B'),
(3,'Dalam teknologi 4G LTE, apa kepanjangan dari LTE?','Long Term Evolution','Limited Telecommunication Equipment','Local Transmission Efficiency','Linear Telecommunication Exchange','A'),
(4,'Apa itu frekuensi dalam konteks telekomunikasi?','Waktu yang dibutuhkan sinyal untuk berpindah lokasi','Jumlah gelombang yang melewati titik tertentu dalam satu detik','Ukuran panjang gelombang elektromagnetik','Satuan kekuatan sinyal','B'),
(5,'Apa itu VoLTE?','Voice over LTE','Video over LTE','Volume Optimization LTE','Virtual LTE','A'),
(6,'Apa peran dari router dalam jaringan telekomunikasi?','Menghubungkan jaringan lokal ke internet','Menyimpan data pelanggan','Mengatur pengaturan perangkat keras jaringan','Mengelola sinyal radio di jaringan','A'),
(7,'Apa itu bandwidth dalam jaringan komunikasi?','Jumlah perangkat yang bisa terhubung ke jaringan','Kapasitas maksimum data yang bisa ditransmisikan dalam waktu tertentu','Jarak antara dua frekuensi radio','Kecepatan koneksi internet','B'),
(8,'Apa perbedaan utama antara jaringan 4G dan 5G?','5G memiliki kecepatan lebih lambat dibandingkan 4G','5G memiliki latensi yang lebih rendah dan kecepatan yang lebih tinggi dibandingkan 4G','4G hanya mendukung komunikasi suara, sedangkan 5G mendukung data','Tidak ada perbedaan signifikan antara keduanya','B'),
(9,'Apa itu teknologi MIMO dalam jaringan telekomunikasi?','Menggunakan beberapa antena untuk meningkatkan kapasitas jaringan','Metode pengelolaan data pelanggan','Teknologi pengurangan gangguan sinyal','Sistem pemrosesan data berbasis cloud','A'),
(10,'Apa itu ping dalam pengujian jaringan?','Sinyal yang digunakan untuk mengukur kekuatan koneksi','Alat untuk mengukur waktu respons antara dua perangkat jaringan','Metode untuk mengatur jaringan lokal','Protokol komunikasi dalam jaringan seluler','B');

/*Table structure for table `quiz_answers` */

DROP TABLE IF EXISTS `quiz_answers`;

CREATE TABLE `quiz_answers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `quiz_id` varchar(4) NOT NULL,
  `question_id` int(11) NOT NULL,
  `answer` varchar(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`,`user_id`,`quiz_id`,`question_id`),
  UNIQUE KEY `uq_user_quiz_question` (`user_id`,`quiz_id`,`question_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25076 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

