/*Table structure for table `quiz_answers_testing` */

DROP TABLE IF EXISTS `quiz_answers_testing`;

CREATE TABLE `quiz_answers_testing` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `quiz_id` varchar(4) NOT NULL,
  `question_id` int(11) NOT NULL,
  `answer` varchar(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`,`user_id`,`quiz_id`,`question_id`),
  UNIQUE KEY `uq_user_quiz_question` (`user_id`,`quiz_id`,`question_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9258 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

