/*Table structure for table `user_quizess` */

DROP TABLE IF EXISTS `user_quizess`;

CREATE TABLE `user_quizess` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `photo` text DEFAULT NULL,
  `status` varchar(15) DEFAULT NULL,
  `long` double DEFAULT NULL,
  `lat` double DEFAULT NULL,
  `datetime` timestamp NULL DEFAULT current_timestamp(),
  `datetime_fake` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1492 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

