/*!50106 DROP EVENT IF EXISTS `auto_logout_users`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`u1687864_barbara_db_admin`@`%` EVENT `auto_logout_users` ON SCHEDULE EVERY 1 MINUTE STARTS '2025-01-31 11:40:20' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    UPDATE users
    SET session_id = NULL
    WHERE last_login_time <= NOW() - INTERVAL 5 MINUTE;
END */$$
